-- =====================================================================================================================
-- Terms of Service and Privacy Policy versions, and who accepted which (MySQL 8)
-- The same schema as the otternova_api migrations, in the order they run:
--   2026-11-25-000001_CreateLegalDocumentTables
--   2026-11-25-000002_SeedLegalDocumentVersions
-- Run either the migrations or this file, not both: the seed below is what the second migration inserts.
-- =====================================================================================================================


-- ---------------------------------------------------------------------------------------------------------------------
-- New tables
-- ---------------------------------------------------------------------------------------------------------------------

-- One row per published version of a document; never changed once in effect. The current version of an audience and
-- type is the one with the latest effective_from that is not in the future.
CREATE TABLE legal_document_version
(
    id                    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    public_id             CHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    audience              ENUM ('B', 'M') DEFAULT 'B'                   NOT NULL, -- B Client app (auth_master), M marketplace customers (customer_master)
    document_type         ENUM ('T', 'P')                               NOT NULL, -- T Terms of Service, P Privacy Policy
    version_label         VARCHAR(32)                                   NOT NULL, -- what people see, e.g. 2025-12-01
    effective_from        DATETIME                                      NOT NULL, -- UTC
    requires_reacceptance ENUM ('Y', 'N') DEFAULT 'Y'                   NOT NULL, -- Y material change: everyone accepts again
    created_by_acc        INT UNSIGNED                                  NULL,     -- the staff member who published it
    created_at            DATETIME DEFAULT CURRENT_TIMESTAMP            NOT NULL,
    CONSTRAINT uq_legal_document_version_public_id UNIQUE (public_id),
    CONSTRAINT uq_legal_document_version_label UNIQUE (audience, document_type, version_label),
    CONSTRAINT fk_legal_document_version_created_by FOREIGN KEY (created_by_acc) REFERENCES auth_master (id)
        ON UPDATE CASCADE ON DELETE SET NULL
)
    COLLATE = utf8mb4_general_ci;

CREATE INDEX audience_document_type_effective_from
    ON legal_document_version (audience, document_type, effective_from);

-- The full text of a version in each language, exactly as shown, with its SHA-256
CREATE TABLE legal_document_text
(
    id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    version_id     INT UNSIGNED                       NOT NULL,
    locale         VARCHAR(16)                        NOT NULL, -- as Config\App::$supportedLocales, e.g. en-US, th
    body           MEDIUMTEXT                         NOT NULL, -- Markdown
    body_sha256    CHAR(64)                           NOT NULL,
    change_summary TEXT                               NULL,     -- what the "we have updated our terms" page says changed
    created_at     DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_legal_document_text_version_locale UNIQUE (version_id, locale),
    CONSTRAINT fk_legal_document_text_version FOREIGN KEY (version_id) REFERENCES legal_document_version (id)
        ON UPDATE CASCADE ON DELETE CASCADE
)
    COLLATE = utf8mb4_general_ci;

-- Append-only: one row per person per version accepted. Exactly one of auth_id and customer_id is set.
-- Deleting the person deletes their rows; the versions themselves are never deleted (RESTRICT).
CREATE TABLE legal_acceptance
(
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    version_id  INT UNSIGNED                       NOT NULL,
    auth_id     INT UNSIGNED                       NULL,
    customer_id INT UNSIGNED                       NULL,
    locale      VARCHAR(16)                        NOT NULL, -- the language they were shown
    context     ENUM ('S', 'I', 'R')               NOT NULL, -- S sign-up, I sign-up from an invitation, R accepting again
    ip_address  VARCHAR(45)                        NOT NULL, -- IPv6 at most
    user_agent  VARCHAR(512)                       NULL,
    accepted_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_legal_acceptance_auth_version UNIQUE (auth_id, version_id),
    CONSTRAINT uq_legal_acceptance_customer_version UNIQUE (customer_id, version_id),
    CONSTRAINT fk_legal_acceptance_version FOREIGN KEY (version_id) REFERENCES legal_document_version (id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_legal_acceptance_auth FOREIGN KEY (auth_id) REFERENCES auth_master (id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_legal_acceptance_customer FOREIGN KEY (customer_id) REFERENCES customer_master (id)
        ON UPDATE CASCADE ON DELETE CASCADE
)
    COLLATE = utf8mb4_general_ci;

CREATE INDEX version_id_accepted_at
    ON legal_acceptance (version_id, accepted_at);


