INSERT INTO legal_document_text (version_id, locale, body, body_sha256)
VALUES (@version_id, 'en-US', 'Last updated: December 1, 2025\n\nWelcome to OtterNova (“we”, “our”, “us”).\nBy using our websites, booking services, or business management platform, you (“you”, “your”, “users”, or “businesses”) agree to these Terms of Service.\n\nThese terms apply to:\n\n - **Main website** (marketing site)\n - **Marketplace site** (for customers booking services or buying products)\n - **Backend system** (for businesses using our platform)\n\nIf you do not agree with these terms, please stop using our services.\n\n## 1. Use of Our Services\n\nYou may use OtterNova only for lawful purposes and in accordance with these Terms.\nYou agree not to:\n\n - Use the service to violate any laws\n - Attempt to hack, disrupt, or damage our systems\n - Misuse the platform in any way that harms other users or businesses\n - Reverse engineer or copy any part of our software\n - Use automated tools to scrape or overload our services\n\nWe reserve the right to suspend accounts that violate these rules.\n\n## 2. Accounts and Security\n\n### For business accounts:\n\nYou must provide accurate information\n\n - You are responsible for keeping your login credentials safe\n - Any actions taken under your account are your responsibility\n - You must ensure your staff also follow these Terms\n\n### For end-customers:\n\nA booking account (if applicable) must contain accurate information\n\n - You are responsible for ensuring the details you provide are correct for booking and communication purposes\n - We are not responsible for losses caused by weak passwords or shared accounts.\n\n## 3. Payments and Subscriptions\n\nSome features of OtterNova are free, while others may require a paid subscription.\n\nBy subscribing to a paid plan, you agree that:\n\n - Fees are billed based on the plan you choose\n - Payments are non-refundable unless required by law\n - Failure to pay may result in suspension of service\n\nWe may adjust pricing with prior notice.\n\n## 4. Data and Content Ownership\n### For businesses:\n\nYou own all data you input into OtterNova, including:\n\n - Services\n - Products\n - Branch information\n - Customer records\n - Booking data\n\nWe do not claim ownership of your data.\n\nYou grant us permission to process this data only as required to operate the system.\n\n### For end-customers:\n\nYou own the personal information you provide during booking.\nWe process it solely to deliver the booking services.\n\nWe do not sell or share data with unrelated third parties.\n\n## 5. Data Management and Deletion\n\nBusinesses may export their data at any time.\nIf you stop using OtterNova, you may request deletion of your information.\n\nCustomer data may be deleted or anonymized upon request, following our Privacy Policy.\n\nWe may retain anonymized, non-identifiable system data for analytics or security.\n\n## 6. Availability and Maintenance\n\nWe aim for high availability, but we cannot guarantee:\n\n - uninterrupted service\n - zero downtime\n - zero bugs\n\nWe may perform maintenance or updates from time to time.\nWe are not liable for losses resulting from temporary unavailability.\n\n## 7. Limitation of Liability\n\nTo the maximum extent permitted by law:\n\n - We are not responsible for indirect, incidental, or consequential damages\n - We are not responsible for losses caused by misuse of the platform\n - We are not responsible for business losses due to incorrect data input, user error, or configuration mistakes\n\nYou agree that use of OtterNova is at your own risk.\n\n## 8. Third-Party Services\n\nOtterNova may integrate with third-party providers such as:\n\n - Payment processors\n - Messaging/email services\n - Analytics tools\n\nWe are not responsible for issues caused by third-party systems.\n\n## 9. Termination\n\nWe may suspend or terminate access to our services if:\n\n - You violate these Terms\n - Payment is overdue\n - Activities pose a security risk\n\nYou may cancel your account at any time.\nUpon cancellation, we may delete or anonymize data as described in our Privacy Policy.\n\n## 10. Changes to These Terms\n\nWe may update these Terms occasionally.\nIf changes are significant, we will notify you through the platform or email.\n\nContinued use of OtterNova means you accept the updated Terms.\n\n## 11. Governing Law\n\nThese Terms are governed by the laws of Thailand.\nAny disputes will fall under the jurisdiction of Thai courts.\n\n## 12. Contact Us\n\nIf you have questions about these Terms, please contact: support@otternova.com',
        'cc1f214d1a8e61445159a17bcc7a9f47a4a9466d5d2567185e0e4285eea8bff0');
INSERT INTO legal_document_text (version_id, locale, body, body_sha256)
VALUES (@version_id, 'th', 'ปรับปรุงล่าสุด: 1 ธันวาคม 2568\n\nยินดีต้อนรับสู่ OtterNova (“เรา”)\nเมื่อคุณใช้งานเว็บไซต์ ระบบมาร์เก็ตเพลส หรือระบบหลังบ้านของเรา ถือว่าคุณยอมรับข้อตกลงนี้\n\nข้อตกลงนี้ครอบคลุม:\n\n - **เว็บไซต์หลัก** (ข้อมูลและการตลาด)\n - **เว็บไซต์มาร์เก็ตเพลส** (สำหรับลูกค้าใช้จองหรือซื้อสินค้า)\n - **ระบบหลังบ้าน** (สำหรับธุรกิจที่ใช้แพลตฟอร์ม)\n\nหากคุณไม่ยอมรับข้อตกลงนี้ กรุณาหยุดใช้งานบริการของเรา\n\n## 1. การใช้งานบริการ\n\nคุณสามารถใช้ OtterNova เพื่อวัตถุประสงค์ที่ถูกต้องตามกฎหมายเท่านั้น\nและต้องไม่กระทำสิ่งต่อไปนี้:\n\n - ใช้ระบบเพื่อทำสิ่งผิดกฎหมาย\n - พยายามแฮ็ก รบกวน หรือทำให้ระบบเสียหาย\n - ใช้งานในลักษณะที่รบกวนผู้อื่น\n - คัดลอก แกะโค้ด หรือดัดแปลงระบบ\n - ใช้บอตหรือระบบอัตโนมัติทำให้เซิร์ฟเวอร์ทำงานผิดปกติ\n\nเราขอระงับการใช้งานของบัญชีที่ละเมิดข้อกำหนดเหล่านี้\n\n## 2. บัญชีและความปลอดภัย\n### สำหรับธุรกิจ:\n\n - ต้องให้ข้อมูลที่ถูกต้อง\n - ต้องรักษาความปลอดภัยของบัญชี\n - การกระทำทั้งหมดภายใต้บัญชีถือเป็นความรับผิดชอบของคุณ\n - ต้องดูแลให้ทีมงานปฏิบัติตามข้อตกลงนี้ด้วย\n\n### สำหรับผู้ใช้ทั่วไป (ลูกค้า):\n\n - ข้อมูลที่ใช้ในการจองต้องถูกต้อง\n - คุณรับผิดชอบต่อข้อมูลที่กรอกในการจองหรือสั่งซื้อ\n\nเราไม่รับผิดชอบความเสียหายที่เกิดจากรหัสผ่านอ่อนแอหรือการแชร์บัญชี\n\n## 3. การชำระเงินและการสมัครแพลน\n\nบริการบางส่วนใช้งานฟรี บางส่วนอาจต้องสมัครแพลนแบบชำระเงิน\n\nเมื่อสมัครแพลนแบบชำระเงิน:\n\n - ค่าบริการคิดตามแพลนที่เลือก\n - ชำระแล้วไม่อาจคืนเงิน ยกเว้นตามที่กฎหมายกำหนด\n - หากชำระเงินไม่สำเร็จ บริการอาจถูกระงับชั่วคราว\n\nกรณีมีการปรับราคา เราจะแจ้งให้ทราบล่วงหน้า\n\n## 4. ความเป็นเจ้าของข้อมูล\n### สำหรับธุรกิจ:\n\nคุณเป็นเจ้าของข้อมูลทั้งหมดที่ใส่ในระบบ เช่น:\n\n - รายการบริการ\n - รายการสินค้า\n - ข้อมูลสาขา\n - รายชื่อลูกค้า\n - ข้อมูลการจอง/คำสั่งซื้อ\n\nเราไม่มีสิทธิ์ในข้อมูลของคุณ\nเราเพียงประมวลผลข้อมูลเพื่อให้ระบบทำงานตามปกติเท่านั้น\n\n### สำหรับลูกค้า (ผู้จอง/ผู้ซื้อ):\n\nคุณเป็นเจ้าของข้อมูลส่วนบุคคลของคุณ\nเราใช้ข้อมูลนั้นเพื่อให้บริการการจองเท่านั้น\n\nเราไม่ขายหรือแบ่งปันข้อมูลกับผู้ให้บริการที่ไม่เกี่ยวข้อง\n\n## 5. การจัดการข้อมูลและการลบข้อมูล\n\nธุรกิจสามารถ ดาวน์โหลด/export ข้อมูลได้ทุกเมื่อ\n\nหากคุณต้องการลบข้อมูล:\n\n - ข้อมูลจะถูกลบหรือทำให้ไม่สามารถระบุตัวบุคคลได้ (anonymize)\n - เราอาจเก็บข้อมูลที่ไม่ระบุตัวตนไว้เพื่อวิเคราะห์หรือรักษาความปลอดภัยของระบบ\n\n## 6. ความพร้อมใช้งานและการบำรุงรักษา\n\nเรามุ่งให้บริการพร้อมใช้งานตลอดเวลา แต่ไม่รับประกันว่า:\n\n - ระบบจะไม่ล่มชั่วคราว\n - จะไม่มีข้อผิดพลาด\n - จะไม่มีการบำรุงรักษา\n\nเราไม่รับผิดชอบความเสียหายจากเหตุระบบล่มชั่วคราว\n\n## 7. ข้อจำกัดความรับผิดชอบ\n\nภายใต้ขอบเขตสูงสุดที่กฎหมายอนุญาต:\n\n - เราไม่รับผิดชอบความเสียหายทางอ้อมหรือผลสืบเนื่อง\n - เราไม่รับผิดชอบต่อความผิดพลาดจากการตั้งค่าหรือข้อมูลผิดของผู้ใช้\n - การใช้งาน OtterNova เป็นความเสี่ยงของผู้ใช้เอง\n\n## 8. บริการจากบุคคลที่สาม\n\nOtterNova อาจเชื่อมกับผู้ให้บริการภายนอก เช่น:\n\n - ระบบชำระเงิน\n - ระบบอีเมล\n - ระบบวิเคราะห์ข้อมูล\n\nเราขอไม่รับผิดชอบต่อความผิดพลาดของบริการภายนอกเหล่านั้น\n\n## 9. การระงับหรือยกเลิกการใช้งาน\n\nเราอาจระงับหรือยกเลิกบัญชีหาก:\n\n - มีการละเมิดข้อตกลง\n - ไม่ชำระค่าบริการ\n - พบพฤติกรรมเสี่ยงต่อความปลอดภัยของระบบ\n\nคุณสามารถยกเลิกบัญชีเมื่อใดก็ได้\nข้อมูลจะถูกลบหรือ anonymize ตามนโยบายความเป็นส่วนตัว\n\n## 10. การปรับปรุงข้อตกลง\n\nเราอาจแก้ไขข้อตกลงนี้เป็นระยะ\nหากมีการเปลี่ยนแปลงสำคัญ เราจะแจ้งให้ทราบ\n\nการใช้งานต่อถือว่าคุณยอมรับข้อตกลงใหม่\n\n## 11. กฎหมายที่ใช้บังคับ\n\nข้อตกลงนี้อยู่ภายใต้กฎหมายของประเทศไทย ข้อพิพาทใด ๆ จะอยู่ภายใต้ศาลไทย\n\n## 12. ติดต่อเรา\n\nสำหรับคำถามเกี่ยวกับข้อตกลงนี้ ติดต่อได้ที่: support@otternova.com',
        'a49bb96c43a38cbaf509dc22a2abc078bf313072d9c75527fa63e6715a6f30d9');

