INSERT INTO legal_document_text (version_id, locale, body, body_sha256)
VALUES (@version_id, 'en-US', 'Last updated: December 1, 2025\n\nOtterNova (“we”, “our”, “us”) provides online business tools and booking systems designed to make scheduling and operations simpler.\nWe care about privacy and collect only what is necessary to deliver our services, nothing more.\n\nThis Privacy Policy applies to:\n\n - OtterNova Main Website (marketing site)\n - OtterNova Marketplace Website (for end-customers)\n - OtterNova Backend System (for business users)\n\n## 1. Information We Collect\n### 1.1 Main Website (Marketing Site)\n\nWe do not collect personal information.\nWe only use Google Analytics to understand website traffic and improve our content.\n\nThis includes:\n\n - Pages visited\n - Browser/OS/device information\n - Approximate location (city-level)\n - Time spent on site\n\n**No** names, emails, phone numbers, or sensitive data are collected here.\n\n### 1.2 Marketplace Website (End-Customer Use)\n\nThis site allows end-users to book services or buy products from businesses using OtterNova.\n\nWe collect only the minimum data required for booking or order fulfillment, such as:\n\nFor service bookings:\n\n - Name\n - Email address\n - (Optional) Phone number\n\nFor product purchases:\n\n - Name\n - Email address\n - Shipping address (only if delivery is required)\n - (Optional) Phone number\n\nNo address is collected if:\n\n - The product is digital, or\n - The customer chooses self pick-up\n\nWe do **not** collect unnecessary or sensitive information.\n\n### 1.3 Backend System (For Businesses Using OtterNova)\n\nBusiness users use our platform to manage operations.\nWe collect and store information required for system functionality, including:\n\n - Business profile\n - Branches and branch addresses\n - Services and service details\n - Products, prices, stock, and related configurations\n - Staff information (names, roles, emails)\n - Customer booking and order data\n\nWe do **not** use this operational data for advertising, tracking, or selling to third parties.\n\n## 2. How We Use the Information\n\nWe use collected data for purposes such as:\n\n - Providing booking and scheduling features\n - Processing orders and payments\n - Communicating booking confirmations or updates\n - Managing business accounts and system functions\n - Improving platform performance and reliability\n - Securing accounts and preventing misuse\n\nWe do **not** sell, rent, trade, or share personal data with external marketers or unrelated third parties.\n\n## 3. Data Security\n\nWe store data using industry-level security standards similar to what is used in banking and fintech systems.\nThis includes:\n\n - Encrypted connections (HTTPS)\n - Secured databases\n - Access controls\n - Regular security checks\n\nOnly authorized personnel can access data when necessary to maintain the system.\n\n## 4. Data Retention and Anonymization\n\nWe retain user information only as long as required for operational or legal purposes.\n\nIf a user or business requests deletion:\n\n - The data will be deleted or anonymized\n - Anonymization will be used if deleting the record would break system integrity (e.g., business analytics, transaction history)\n\nWe do not keep personal data longer than needed.\n\n## 5. Your Rights\n\nDepending on your region, you may have the right to:\n\n - Access your data\n - Correct inaccurate information\n - Request data deletion\n - Export or transfer your data\n - Withdraw consent for optional processing\n\nWe will respond to these requests within a reasonable time.\n\nBusinesses using OtterNova can export their operational data at any time and may stop using our service whenever they choose.\n\n## 6. Cookies and Tracking\n\n### Main website:\n\n - Uses Google Analytics\n - Only for visitor insights\n - No personal information collected\n - No marketing/advertising cookies used\n\n### Marketplace website & backend system:\n\n - Only essential cookies (such as login sessions)\n - No tracking or advertising cookies\n\n## 7. Third-Party Services\n\nWe use trusted third-party providers only when necessary for:\n\n - Analytics\n - Hosting\n - Payment processing\n\nThese providers only receive the minimum data needed to perform their services and must follow privacy and security standards.\n\n## 8. Data Transfers\n\nOur platform may store or process data in multiple regions depending on server infrastructure.\nWe ensure that all transfers comply with international privacy standards such as GDPR or local PDPA requirements.\n\n## 9. Updates to This Policy\n\nWe may update this policy occasionally to comply with legal requirements or improve clarity.\nWhen updates occur, the “Last updated” date will change.\n\n## 10. Contact Us\n\nFor any privacy-related questions or requests, contact our team at: support@otternova.com',
        '9ee1d8e31fad4031f888f9f4dd6cf4517e631100e0d518c5370224ea93d9a59e');
INSERT INTO legal_document_text (version_id, locale, body, body_sha256)
VALUES (@version_id, 'th', 'ปรับปรุงล่าสุด: 1 ธันวาคม 2568\n\nOtterNova (“เรา”) ให้บริการระบบออนไลน์ที่ช่วยให้ธุรกิจจัดการการจองและการดำเนินงานได้ง่ายขึ้น\nเราคำนึงถึงความเป็นส่วนตัวของผู้ใช้และเก็บข้อมูลเท่าที่จำเป็นเท่านั้น\n\nนโยบายฉบับนี้ครอบคลุมการใช้งานบน:\n\n - เว็บไซต์หลักของ OtterNova (เว็บไซต์ประชาสัมพันธ์)\n - เว็บไซต์มาร์เก็ตเพลสของ OtterNova (สำหรับผู้ใช้ทั่วไปที่ต้องการจอง/สั่งซื้อ)\n - ระบบหลังบ้านของ OtterNova (สำหรับธุรกิจผู้ใช้งานระบบ)\n\n## 1. ข้อมูลที่เราเก็บ\n### 1.1 เว็บไซต์หลัก (Marketing Site)\n\nเว็บไซต์นี้ ไม่เก็บข้อมูลส่วนบุคคล\nเราใช้เพียง Google Analytics เพื่อวิเคราะห์พฤติกรรมผู้เข้าชม เพื่อปรับปรุงเนื้อหาเท่านั้น โดยข้อมูลที่เก็บ ได้แก่:\n\n - หน้าเว็บที่เข้าชม\n - อุปกรณ์/เบราว์เซอร์\n - ข้อมูลตำแหน่งโดยประมาณ (ระดับเมือง)\n - ระยะเวลาที่ใช้งาน\n\n**ไม่**มีการเก็บชื่อ อีเมล เบอร์โทร หรือข้อมูลส่วนตัวใด ๆ\n\n### 1.2 เว็บไซต์มาร์เก็ตเพลส (สำหรับลูกค้าที่จอง/ซื้อสินค้า)\n\nเว็บไซต์นี้ใช้สำหรับผู้ใช้ทั่วไปที่ต้องการจองบริการหรือซื้อสินค้า เราเก็บข้อมูล เฉพาะเท่าที่จำเป็น ต่อการดำเนินงานเท่านั้น เช่น:\n\nสำหรับการจองบริการ:\n\n - ชื่อ\n - อีเมล\n - เบอร์โทร (ถ้ามี/ถ้าผู้ใช้ต้องการให้)\n\nสำหรับการซื้อสินค้า:\n\n - ชื่อ\n - อีเมล\n - ที่อยู่สำหรับจัดส่ง (เฉพาะกรณีต้องจัดส่งสินค้า)\n - เบอร์โทร (ถ้าจำเป็นต่อการจัดส่ง)\n\nกรณีไม่ต้องจัดส่ง เช่น รับเองที่ร้าน หรือเป็นสินค้าดิจิทัล จะ **ไม่เก็บ** ที่อยู่\n\nเรา**ไม่**เก็บข้อมูลที่ไม่จำเป็น\n\n### 1.3 ระบบหลังบ้าน (สำหรับธุรกิจผู้ใช้งาน OtterNova)\n\nสำหรับเจ้าของธุรกิจที่ล็อกอินเข้าใช้งานระบบ เราจะเก็บข้อมูลที่จำเป็นต่อการดำเนินงานของระบบ เช่น:\n\n - โปรไฟล์ธุรกิจ\n - สาขาและที่อยู่\n - รายการบริการ รายการสินค้า ราคา\n - ข้อมูลพนักงาน (ชื่อ อีเมล ตำแหน่ง)\n - ข้อมูลคำสั่งซื้อและการจองของลูกค้า\n\nเรา**จะไม่**นำข้อมูลการดำเนินงานของธุรกิจไปขาย ใช้ทำการตลาด หรือแชร์กับบุคคลที่สามที่ไม่เกี่ยวข้อง\n\n## 2. วัตถุประสงค์ในการใช้ข้อมูล\n\nเราใช้ข้อมูลเพื่อ:\n\n - ให้บริการด้านการจองและระบบจัดการ\n - ประมวลผลคำสั่งซื้อและการชำระเงิน\n - ส่งอีเมลแจ้งเตือน/ยืนยันการจอง\n - จัดการบัญชีผู้ใช้งานของธุรกิจ\n - ปรับปรุงประสิทธิภาพของระบบ\n - รักษาความปลอดภัยของบัญชีและป้องกันการใช้งานผิดวิธี\n\nเรา**ไม่**ขาย ไม่เช่า ไม่แลกเปลี่ยนข้อมูลส่วนบุคคลกับผู้ให้บริการโฆษณา\n\n## 3. การเก็บรักษาความปลอดภัยของข้อมูล\n\nข้อมูลทั้งหมดถูกจัดเก็บในระบบฐานข้อมูลที่มีมาตรฐานความปลอดภัยในระดับเดียวกับที่ใช้ในระบบการเงิน เช่น:\n\n - การเชื่อมต่อแบบเข้ารหัส (HTTPS)\n - ฐานข้อมูลที่มีระบบรักษาความปลอดภัยมาตรฐาน\n - การควบคุมสิทธิ์เข้าถึง\n - การตรวจสอบความปลอดภัยเป็นประจำ\n\nเฉพาะเจ้าหน้าที่ที่ได้รับอนุญาตเท่านั้นที่สามารถเข้าถึงข้อมูลในกรณีที่จำเป็นต่อการดูแลระบบ\n\n## 4. ระยะเวลาในการเก็บข้อมูลและการลบข้อมูล\n\nเราจะเก็บข้อมูลเท่าที่จำเป็นต่อวัตถุประสงค์ของระบบเท่านั้น\n\nหากผู้ใช้หรือลูกค้าต้องการลบข้อมูล:\n\n - ข้อมูลจะถูก ลบหรือทำให้ไม่สามารถระบุตัวบุคคลได้ (anonymize)\n - เราจะใช้การ anonymize หากการลบข้อมูลแบบสมบูรณ์อาจส่งผลต่อความสมบูรณ์ของระบบ เช่น รายงานยอดขาย หรือประวัติธุรกรรม\n\nเราไม่เก็บข้อมูลไว้นานเกินความจำเป็น\n\n## 5. สิทธิของผู้ใช้\n\nขึ้นอยู่กับกฎหมายในแต่ละพื้นที่ ผู้ใช้อาจมีสิทธิ:\n\n - ขอเข้าถึงข้อมูลส่วนตัว\n - แก้ไขข้อมูล\n - ขอให้ลบข้อมูล\n - ขอคัดลอกหรือโอนย้ายข้อมูล\n - ถอนความยินยอม (เฉพาะข้อมูลที่ต้องใช้ consent)\n\nธุรกิจผู้ใช้งาน OtterNova สามารถ ดาวน์โหลด/export ข้อมูล ได้ตลอดเวลา\nและสามารถหยุดใช้งานบริการของเราได้เมื่อใดก็ได้\n\n## 6. คุกกี้ที่เราใช้\n### เว็บไซต์หลัก:\n\n - ใช้ Google Analytics เท่านั้น\n - ไม่ใช้คุกกี้โฆษณา\n - ไม่เก็บข้อมูลส่วนบุคคล\n\n### เว็บไซต์มาร์เก็ตเพลส & ระบบหลังบ้าน:\n\n - ใช้เฉพาะคุกกี้ที่จำเป็น เช่น session สำหรับล็อกอิน\n - ไม่ใช้คุกกี้เพื่อการตลาด\n\n## 7. ผู้ให้บริการภายนอก\n\nเราใช้ผู้ให้บริการบางรายเพื่อช่วยดำเนินการ เช่น:\n\n - ระบบวิเคราะห์ข้อมูล\n - ระบบโฮสติ้ง\n - ระบบชำระเงิน\n\nผู้ให้บริการเหล่านี้จะได้รับข้อมูลเท่าที่จำเป็นเท่านั้น และต้องปฏิบัติตามมาตรฐานความปลอดภัย\n\n## 8. การโอนย้ายข้อมูลระหว่างประเทศ\n\nข้อมูลอาจถูกจัดเก็บหรือประมวลผลในเซิร์ฟเวอร์ต่างประเทศตามโครงสร้างพื้นฐานของเรา\nเรารับรองว่าการโอนข้อมูลระหว่างประเทศจะเป็นไปตามกฎหมายคุ้มครองข้อมูลส่วนบุคคลที่เกี่ยวข้อง\n\n## 9. การปรับปรุงนโยบายนี้\n\nเราอาจอัปเดตนโยบายเป็นครั้งคราวเพื่อปรับให้สอดคล้องกับกฎหมายหรือการพัฒนาบริการ\nเมื่อมีการปรับปรุง เราจะแก้ไขวันที่ “ปรับปรุงล่าสุด” ด้านบน\n\n## 10. การติดต่อเรา\n\nหากมีคำถามหรือคำร้องเกี่ยวกับข้อมูลส่วนบุคคล สามารถติดต่อทีมงานได้ที่: support@otternova.com',
        '92302d01c01a7c72051abb8c540591f21144b6da27bf1fbeaded62e5b92e7f2f');
